INSERT INTO `email_templates` (`id`, `code`, `name`, `subject`, `body_html`, `description`, `variables`, `is_active`, `updated_by_id`, `created_at`, `updated_at`) VALUES
(1, 'employee_onboarding', 'Employee onboarding', 'Welcome to {{ company_name }}, {{ employee_name }}!', '<p>Hi {{ employee_name }},</p>\n<p>Welcome aboard! Your employee profile has been created.</p>\n<table style=\"border-collapse:collapse\">\n<tr><td style=\"padding:2px 12px 2px 0;color:#6b7280\">Employee ID</td><td><b>{{ employee_code }}</b></td></tr>\n<tr><td style=\"padding:2px 12px 2px 0;color:#6b7280\">Designation</td><td>{{ designation or \'-\' }}</td></tr>\n<tr><td style=\"padding:2px 12px 2px 0;color:#6b7280\">Department</td><td>{{ department or \'-\' }}</td></tr>\n<tr><td style=\"padding:2px 12px 2px 0;color:#6b7280\">Joining date</td><td>{{ joining_date }}</td></tr>\n<tr><td style=\"padding:2px 12px 2px 0;color:#6b7280\">Login email</td><td>{{ email }}</td></tr>\n</table>\n{% if set_password_url %}\n<p>Please set your password to activate your account (link valid for 72 hours):</p>\n<p><a href=\"{{ set_password_url }}\" style=\"background:#4f46e5;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none\">Set my password</a></p>\n{% else %}\n<p>Your HR team will share your temporary password separately. You will be asked to change it at first login: <a href=\"{{ login_url }}\">{{ login_url }}</a></p>\n{% endif %}\n<p>Regards,<br>HR Team</p>', 'Sent to a new employee when their profile is created', 'employee_name, employee_code, email, designation, department, joining_date, login_url, set_password_url', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18'),
(2, 'leave_applied', 'Leave application (to approvers)', 'Leave request: {{ employee_name }} ({{ days }} day{{ \'\' if days == 1 else \'s\' }})', '<p>Hi {{ approver_name }},</p>\n<p><b>{{ employee_name }}</b> ({{ employee_code }}) has applied for <b>{{ leave_type }}</b>.</p>\n<ul>\n<li>Period: {{ start_date }} to {{ end_date }} ({{ days }} working day(s))</li>\n{% if lop_days and lop_days > 0 %}<li style=\"color:#b45309\">Estimated Loss of Pay: {{ lop_days }} day(s) (insufficient balance)</li>{% endif %}\n<li>Reason: {{ reason }}</li>\n</ul>\n<p><a href=\"{{ review_url }}\">Review the request</a></p>', 'Sent to HR/Admin approvers when an employee applies for leave', 'approver_name, employee_name, employee_code, leave_type, start_date, end_date, days, lop_days, reason, review_url', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18'),
(3, 'leave_applied_confirmation', 'Leave application (to employee)', 'Your {{ leave_type }} request has been submitted', '<p>Hi {{ employee_name }},</p>\n<p>Your <b>{{ leave_type }}</b> request for {{ start_date }} to {{ end_date }} ({{ days }} day(s)) has been submitted and is pending approval.</p>\n{% if lop_days and lop_days > 0 %}<p style=\"color:#b45309\">Note: based on your current balance, {{ lop_days }} day(s) may be treated as Loss of Pay.</p>{% endif %}\n<p>Regards,<br>HR Team</p>', 'Acknowledgement sent to the employee after applying for leave', 'employee_name, leave_type, start_date, end_date, days, lop_days', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18'),
(4, 'leave_status', 'Leave approved / rejected', 'Your {{ leave_type }} request has been {{ status }}', '<p>Hi {{ employee_name }},</p>\n<p>Your <b>{{ leave_type }}</b> request for {{ start_date }} to {{ end_date }} ({{ days }} day(s)) has been\n<b style=\"color:{{ \'#15803d\' if status == \'approved\' else \'#b91c1c\' }}\">{{ status }}</b> by {{ reviewer_name }}.</p>\n{% if status == \'approved\' %}<p>Paid days: {{ paid_days }}{% if lop_days and lop_days > 0 %} &middot; <span style=\"color:#b45309\">Loss of Pay days: {{ lop_days }}</span>{% endif %}</p>{% endif %}\n{% if comment %}<p>Comment: <i>{{ comment }}</i></p>{% endif %}\n<p>Regards,<br>HR Team</p>', 'Sent to the employee when a leave request is approved or rejected', 'employee_name, leave_type, start_date, end_date, days, status, paid_days, lop_days, comment, reviewer_name', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18'),
(5, 'payslip_generated', 'Salary slip generated', 'Your salary slip for {{ period }} is available', '<p>Hi {{ employee_name }},</p>\n<p>Your salary slip for <b>{{ period }}</b> has been generated.</p>\n<p>Net salary: <b>&#8377; {{ net_salary }}</b><br>Paid days: {{ paid_days }}{% if lop_days and lop_days > 0 %} &middot; LOP days: {{ lop_days }}{% endif %}</p>\n<p><a href=\"{{ payslip_url }}\">View and download your payslip</a></p>', 'Sent to each employee when payroll is locked and the payslip PDF is available', 'employee_name, period, net_salary, paid_days, lop_days, payslip_url', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18'),
(6, 'payroll_processed', 'Payroll processed (to admins)', 'Payroll {{ action }}: {{ period }}', '<p>Hi {{ recipient_name }},</p>\n<p>The payroll for <b>{{ period }}</b> was <b>{{ action }}</b> by {{ actor_name }}.</p>\n<ul><li>Employees: {{ employee_count }}</li><li>Total gross: &#8377; {{ total_gross }}</li><li>Total net payout: &#8377; {{ total_net }}</li></ul>', 'Sent to payroll administrators when a payroll run is locked or credited', 'recipient_name, period, action, employee_count, total_gross, total_net, actor_name', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18'),
(7, 'salary_credited', 'Salary credited', 'Salary credited for {{ period }}', '<p>Hi {{ employee_name }},</p>\n<p>Your salary of <b>&#8377; {{ net_salary }}</b> for {{ period }} has been credited to account {{ bank_account or \'on file\' }}.</p>\n<p>Transaction reference: <code>{{ transaction_ref }}</code></p>', 'Sent to the employee when the (simulated) salary credit is completed', 'employee_name, period, net_salary, transaction_ref, bank_account', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18'),
(8, 'password_reset', 'Password reset', 'Reset your {{ company_name }} HRMS password', '<p>Hi {{ user_name }},</p>\n<p>We received a request to reset your password. This link is valid for {{ expires_hours }} hours:</p>\n<p><a href=\"{{ reset_url }}\" style=\"background:#4f46e5;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none\">Reset password</a></p>\n<p>If you didn\'t request this, you can ignore this email.</p>', 'Sent when a password reset is requested', 'user_name, reset_url, expires_hours', 1, NULL, '2026-10-05 08:42:18', '2026-10-05 08:42:18');
